static struct TreeNode *build(int *inorder, int inStart, int inEnd, int *postorder, int postStart, int postEnd) {
  if (inStart > inEnd) return NULL;
  int rootVal = postorder[postEnd];
  int idx = inStart;
  while (inorder[idx] != rootVal) idx++;
  int leftLen = idx - inStart;
  struct TreeNode *root = (struct TreeNode *)malloc(sizeof(struct TreeNode));
  root->val = rootVal;
  root->left = build(inorder, inStart, idx - 1, postorder, postStart, postStart + leftLen - 1);
  root->right = build(inorder, idx + 1, inEnd, postorder, postStart + leftLen, postEnd - 1);
  return root;
}

struct TreeNode *buildTree(int *inorder, int inorderSize, int *postorder, int postorderSize) {
  return build(inorder, 0, inorderSize - 1, postorder, 0, postorderSize - 1);
}

class Solution {
  TreeNode *build(vector<int> &inorder, int inStart, int inEnd, vector<int> &postorder, int postStart, int postEnd) {
    if (inStart > inEnd) return nullptr;
    int rootVal = postorder[postEnd];
    int idx = inStart;
    while (inorder[idx] != rootVal) idx++;
    int leftLen = idx - inStart;
    TreeNode *root = new TreeNode(rootVal);
    root->left = build(inorder, inStart, idx - 1, postorder, postStart, postStart + leftLen - 1);
    root->right = build(inorder, idx + 1, inEnd, postorder, postStart + leftLen, postEnd - 1);
    return root;
  }

public:
  TreeNode *buildTree(vector<int> &inorder, vector<int> &postorder) {
    return build(inorder, 0, (int)inorder.size() - 1, postorder, 0, (int)postorder.size() - 1);
  }
};

func buildTree(inorder []int, postorder []int) *TreeNode {
	var build func(inStart, inEnd, postStart, postEnd int) *TreeNode
	build = func(inStart, inEnd, postStart, postEnd int) *TreeNode {
		if inStart > inEnd {
			return nil
		}
		rootVal := postorder[postEnd]
		idx := inStart
		for inorder[idx] != rootVal {
			idx++
		}
		leftLen := idx - inStart
		root := &TreeNode{Val: rootVal}
		root.Left = build(inStart, idx-1, postStart, postStart+leftLen-1)
		root.Right = build(idx+1, inEnd, postStart+leftLen, postEnd-1)
		return root
	}
	return build(0, len(inorder)-1, 0, len(postorder)-1)
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private TreeNode build(int[] inorder, int inStart, int inEnd, int[] postorder, int postStart, int postEnd) {
    if (inStart > inEnd) return null;
    int rootVal = postorder[postEnd];
    int idx = inStart;
    while (inorder[idx] != rootVal) idx++;
    int leftLen = idx - inStart;
    TreeNode root = new TreeNode(rootVal);
    root.left = build(inorder, inStart, idx - 1, postorder, postStart, postStart + leftLen - 1);
    root.right = build(inorder, idx + 1, inEnd, postorder, postStart + leftLen, postEnd - 1);
    return root;
  }

  public TreeNode buildTree(int[] inorder, int[] postorder) {
    return build(inorder, 0, inorder.length - 1, postorder, 0, postorder.length - 1);
  }
}

class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        def build(in_start, in_end, post_start, post_end):
            if in_start > in_end:
                return None
            root_val = postorder[post_end]
            idx = in_start
            while inorder[idx] != root_val:
                idx += 1
            left_len = idx - in_start
            root = TreeNode(root_val)
            root.left = build(in_start, idx - 1, post_start, post_start + left_len - 1)
            root.right = build(idx + 1, in_end, post_start + left_len, post_end - 1)
            return root

        return build(0, len(inorder) - 1, 0, len(postorder) - 1)

impl Solution {
  pub fn build_tree(inorder: Vec<i32>, postorder: Vec<i32>) -> Option<Box<TreeNode>> {
    Self::build(&inorder, &postorder)
  }

  fn build(inorder: &[i32], postorder: &[i32]) -> Option<Box<TreeNode>> {
    if inorder.is_empty() {
      return None;
    }
    let root_val = postorder[postorder.len() - 1];
    let idx = inorder.iter().position(|&x| x == root_val).unwrap();
    let mut root = Box::new(TreeNode::new(root_val));
    root.left = Self::build(&inorder[..idx], &postorder[..idx]);
    root.right = Self::build(&inorder[idx + 1..], &postorder[idx..postorder.len() - 1]);
    Some(root)
  }
}

const buildTree = (inorder: number[], postorder: number[]): TreeNode | null => {
  const build = (inStart: number, inEnd: number, postStart: number, postEnd: number): TreeNode | null => {
    if (inStart > inEnd) return null;
    const rootVal = postorder[postEnd];
    let idx = inStart;
    while (inorder[idx] !== rootVal) idx++;
    const leftLen = idx - inStart;
    const root = new TreeNode(rootVal);
    root.left = build(inStart, idx - 1, postStart, postStart + leftLen - 1);
    root.right = build(idx + 1, inEnd, postStart + leftLen, postEnd - 1);
    return root;
  };
  return build(0, inorder.length - 1, 0, postorder.length - 1);
};
